@@ -0,0 +1,24 @@
+// Sites: each location belongs to one site, and a batch belongs to the site of
+// its location. Items, suppliers, recipes and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site a request without an `X-Larder-Site` header uses. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The ids of the locations in a site. */
+export function siteLocationIds(store, site) {
+  return new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+}
+
+/** A predicate that is true for the batches stored in `site`. */
+export function inSite(store, site) {
+  const ids = siteLocationIds(store, site);
+  return (batch) => ids.has(batch.location);
+}
